  document.getElementById("upload_message").addEventListener("click", fileFunction);

  function fileFunction() {
  console.log("we are in upload function in jS")
  var message = document.getElementById("input-message");
  var file_data = document.getElementById("input-file");
  var img_data = document.getElementById("input-img");

  var client_url = "";
  var partner_id = "";

  console.log("==================client_url: ", client_url); 

  if (file_data.files.length > 0) {
    var file = file_data.files[0];
    console.log("file length: ",file_data.files.length)
    console.log("file: ",file_data.files[0])

  }

  if (img_data.files.length > 0) {
    var file = img_data.files[0];
    console.log("file length: ",img_data.files.length)
    console.log("file: ",img_data.files[0])

  }
  console.log("log note: ",message.value)
  var formData = new FormData();
  formData.append('record_id', );
  formData.append('model','purchase.order');
  formData.append('note', message.value);
  formData.append('file_attachment', file_data.files[0]);
  formData.append('img_attachment', img_data.files[0]);
  if(file_data.files[0])
    {
    formData.append('file_attachment_name', file_data.files[0].name);
    formData.append('file_attachment_type', file_data.files[0].type);
    }
 if(img_data.files[0])
    {
    formData.append('img_attachment_name', img_data.files[0].name);
    formData.append('img_attachment_type', img_data.files[0].type);
    }
  if (client_url) {
    formData.append('client_url', client_url);
  }
  if (partner_id) {
    formData.append('partner_id', partner_id);
  }
  console.log("======================",formData)
  if (message.value) {
    fetch('/message/note', {
      method: 'POST',
      body: formData,
    })
    .then(response => response.json())
    .then(data => {
      document.getElementById("input-message").value ='';
      document.getElementById("input-file").value ='';
      document.getElementById("input-img").value ='';
      console.log("respone :: ",data);
      location.reload();
    })
    .catch(error => {
      console.error(error);
    });
  }
  else
  {
  alert("Please Enter log note to update.")
  }
  }
  function openPDFPopup() {
      var modal = document.getElementById("pdfPopup");
      modal.style.display = "block";
    }

  function cancelPdfPopup() {
      var modal = document.getElementById("pdfPopup");
      modal.style.display = "none";
    }

  function openSubmitPopup() {
      var percentage = document.querySelector('input[name="radio_payment_terms"]:checked');
      var client_url = "";
      var partner_id = "";
      var invoice_amount_text = document.getElementById("invoice-amount").value;
      let invoice_amount_str = invoice_amount_text.replace(/,/g, '');
      let invoice_amount = parseFloat(invoice_amount_str);
      var po_amount = parseFloat(document.getElementById('po-amount').value);
      var invoice_no = document.getElementById('input-invoice').value;
      var calculated_amount = parseFloat(document.getElementById('calculate_amount').value);
      var formData = new FormData();
      formData.append('invoice_no', invoice_no);
      formData.append('record_id', );
      formData.append('percentage', percentage.value);
      formData.append('invoice_amount', invoice_amount);
      formData.append('po_amount', po_amount);
      formData.append('calculate_amount', calculated_amount);

      if (client_url) {
        formData.append('client_url', client_url);
      }
      if (partner_id) {
        formData.append('partner_id', partner_id);
      }

      // Send AJAX request to the Odoo controller
      fetch('/vendor/check/invoice/duplicate', {
          method: 'POST',
          body: formData,
      })
      .then(response => {
          // Check if response is OK
          if (response.ok) {
              return response.text();
          } else {
              return response.text().then(text => {
                  throw new Error('Server error: ' + text);
              });
          }
      })
      .then(text => {
          try {
              // Parse response text as JSON
              const data = JSON.parse(text);

              // Extract 'duplicate' from the data
              console.log("==================================duplicate===",data)
              if (data.duplicate !== undefined) {
                  if (data.duplicate_invoices) {
                      // Handle the case where a duplicate invoice is found
                      var payment_validation = document.getElementById('invoice_id_validation');
                      payment_validation.innerHTML= 'A duplicate invoice number has been found.';
                  }else if (data.mismatch_amount) {
                      var amount_validation = document.getElementById('amount_validation');
                      amount_validation.innerHTML= 'The amount on the uploaded invoice does not match with PO amount.';
                  } else {
                      // Handle the case where no duplicate invoice is found
                       var modal = document.getElementById("submitPopup");
                        modal.style.display = "block";
                        document.getElementById("pdfPopup").style.display = "none";
                  }
              } else if (data.error) {
                  // Handle error in the response
                  console.error('Error:', data.error);
              } else {
                  // Handle unexpected response format
                  console.error('Unexpected response format:', data);
              }
          } catch (error) {
              console.error('Error parsing JSON:', error);
          }
      })
      .catch(error => {
          console.error('Error:', error);
      });
  }

  function openSubmitSucessfullPopup() {
        var modal = document.getElementById("submitSucessfullPopup");
        modal.style.display = "block";
    }
  function openErrorPopup() {
        var modal = document.getElementById("submitErrorPopup");
