  document.querySelectorAll(".drop-zone__input").forEach((inputElement) => {
    const dropZoneElement = inputElement.closest(".drop-zone");

    // Open file dialog on click
    dropZoneElement.addEventListener("click", (e) => {
      inputElement.click();
    });

    // Handle file selection
    inputElement.addEventListener("change", (e) => {
      if (inputElement.files.length) {
        updateThumbnail(dropZoneElement, inputElement.files[0]);
      }
    });

    // Handle drag over
    dropZoneElement.addEventListener("dragover", (e) => {
      e.preventDefault();
      dropZoneElement.classList.add("drop-zone-over");
    });

    // Handle drag leave and drag end
    ["dragleave", "dragend"].forEach((type) => {
      dropZoneElement.addEventListener(type, (e) => {
        dropZoneElement.classList.remove("drop-zone-over");
      });
    });

    // Handle file drop
    dropZoneElement.addEventListener("drop", (e) => {
      e.preventDefault();
      dropZoneElement.classList.remove("drop-zone-over");

      if (e.dataTransfer.files.length) {
        inputElement.files = e.dataTransfer.files;
        updateThumbnail(dropZoneElement, e.dataTransfer.files[0]);
      }
    });
  });

  /**
   * Updates the thumbnail or shows an error message if the file is invalid.
   *
   * @param {HTMLElement} dropZoneElement
   * @param {File} file
   */
  function updateThumbnail(dropZoneElement, file) {
    const thumbnailElement = dropZoneElement.querySelector(".drop-zone__thumb");
    const fileInput = document.getElementById("input-invoice-file");
    if (fileInput.files.length > 0 && fileInput.files[0].type!='application/pdf') {
      // Clear the file input and show an error
      //fileInput.value = '';
      //dropZoneElement.classList.remove("drop-zone-over");
      //if (thumbnailElement) {
      //  thumbnailElement.style.backgroundImage = null;
      //}
      var file = fileInput.files[0];
      console.log("file length: ",fileInput.files.length)
      console.log("file: ",fileInput.files[0])
      console.log("file: ",fileInput.files[0].name)
      console.log("file: ",fileInput.files[0].type)
      document.getElementById("input-invoice").value ='';
      document.getElementById("input-invoice-file").value ='';
      pdfFileName.innerHTML = '';
      document.getElementById('pdfIframe').src = " ";
      document.getElementById('pdfIframe1').src = " ";
      dropZoneElement.classList.remove("drop-zone-over");
      alert("Please upload PDF file only2.");
      return;
    }
    else{
