    }
  }

// Cancel Preview Invoice
document.getElementById("cancel_draft_invoice").addEventListener("click", cancelPreviewInvoice);
  function cancelPreviewInvoice() {
      let reqDetails = document.getElementById("reqDetails")
      reqDetails.style.removeProperty("display");
      document.getElementById("saveBox").style.display = "block";
      document.getElementById("submit_invoice_record").style.display = "block";
      document.getElementById("submitButton").style.display = "none";
      document.getElementById("submitButton1").style.display = "none";
      document.getElementById("poTotal").style.display = "none";
      document.getElementById("pdfPopup").style.display = "none";
  }



  function handleFileChangeEvent() {
    const fileInput = document.getElementById('input-invoice-file');
    const pdffile = fileInput.files[0];

    if (pdffile) {
      const embed = document.createElement('embed');
      embed.src = URL.createObjectURL(pdffile);
      embed.type = 'application/pdf';
      embed.width = '100%';
      embed.height = '600px'; // Adjust height as needed

      const pdfContainer = document.getElementById('pdfContainer');
      pdfContainer.innerHTML = '';
      pdfContainer.appendChild(embed);

      const formData = new FormData();
      formData.append('file', pdffile);

      fetch('/ocr/upload', {
        method: 'POST',
        body: formData,
      })
      .then(response => response.json())
      .then(data => {
        document.getElementById("input-invoice").value = data.invoice_no;
        document.getElementById("invoice-amount").value = data.amount;

        document.getElementById("ocr_invoice_number").value = data.invoice_no;

        const invoice_no = document.getElementById('input-invoice').value;
        const percentage = document.querySelector('input[name="radio_payment_terms"]:checked');

        if (pdffile && invoice_no.trim() !== '' && percentage && percentage.value !== '') {
          document.getElementById("finalSubmitButton").disabled = false;
          document.getElementById("finalSubmitButton").style.background = "#3462ae";
          document.getElementById("submitButton1").style.background = "#3462ae";
          document.getElementById("div_submit_invoice_record").style.border = "1px solid #3462ae"; 
          document.getElementById("submit_invoice_record").style.color = "#3462ae";
        } else {
          document.getElementById("finalSubmitButton").disabled = true;
          document.getElementById("finalSubmitButton").style.background = "#d2d2d2";
          document.getElementById("submitButton1").style.background = "#d2d2d2";
          document.getElementById("submit_invoice_record").style.color = "#bcbbbb";
          document.getElementById("div_submit_invoice_record").style.border = "1px solid #d2d2d2"; 
        }
      })
      .catch(error => {
        console.error('Error:', error);
        document.getElementById('ocr-result').innerText = 'An error occurred during OCR processing.';
      });
    }
  }

  document.addEventListener('DOMContentLoaded', function() {
    document.getElementById('input-invoice-file').addEventListener('change', handleFileChangeEvent);
  });

 function backToOpenPO() {
    document.getElementById("createInoiceId").style.display = "";
    document.getElementById("previewIvoicePage").style.display = "none";
    document.getElementById("backToOpenPO").style.display = "none";

    document.getElementById("submitButton1").style.display = "block";
    document.getElementById("submit_invoice_record").style.display = "block";
  }
